import {validateServerUrl} from './config.js';
export {configPath,readConfig,saveConfig} from './config.js';

export class CrewRequestError extends Error {
  constructor(message,{code='REQUEST_FAILED',status,details,cause}={}) {
    super(message,{cause});this.name='CrewRequestError';this.code=code;this.status=status;this.details=details;
  }
}
function credential(value,name) {
  if(value!==undefined&&(typeof value!=='string'||/[\r\n\u0000]/.test(value)))throw new Error('Invalid '+name+' credential');
  return value;
}
function requestSignal(options) {
  const duration=options.timeoutMs??15000;
  if(!Number.isSafeInteger(duration)||duration<1)throw new Error('HTTP timeout must be a positive integer');
  const deadline=AbortSignal.timeout(duration);
  return options.signal?AbortSignal.any([options.signal,deadline]):deadline;
}
async function responseData(response) {
  if(response.status===204)return null;
  const text=await response.text();
  if(!text)return null;
  if(!response.headers.get('content-type')?.toLowerCase().includes('json'))return text;
  try{return JSON.parse(text);}
  catch(cause){throw new CrewRequestError('Crew returned an invalid JSON response',{code:'INVALID_RESPONSE',status:response.status,cause});}
}
function failedTransport(cause,signal,options,reading=false) {
  if(cause instanceof CrewRequestError)return cause;
  if(signal.aborted)return new CrewRequestError(options.signal?.aborted?'Crew request cancelled':'Crew request timed out',{code:options.signal?.aborted?'CANCELLED':'TIMEOUT',cause});
  return new CrewRequestError(reading?'Crew response was interrupted. Refresh the resource before repeating a change.':'Cannot reach Crew server',{code:reading?'INCOMPLETE_RESPONSE':'CONNECTION_FAILED',cause});
}
export class CrewClient {
  constructor({url='http://localhost:4100',token,cookie,fetcher=globalThis.fetch}={}) {
    this.url=validateServerUrl(url);this.token=credential(token,'token');this.cookie=credential(cookie,'session');this.fetcher=fetcher;
  }
  async request(method,route,body,options={}) {
    if(typeof route!=='string'||!route.startsWith('/')||route.startsWith('//')||/[\r\n#]/.test(route))throw new Error('Crew API route must start with one slash and use encoded identifiers');
    const headers={'X-Crew-Request':'1',...options.headers};
    if(this.token)headers.Authorization='Bearer '+credential(this.token,'token');
    else if(this.cookie)headers.Cookie=credential(this.cookie,'session');
    const raw=body instanceof Uint8Array||options.stream;
    if(body!==undefined&&!raw)headers['Content-Type']='application/json';
    const signal=requestSignal(options);
    let response;
    try{
      response=await this.fetcher(this.url+'/api/v1'+route,{method,headers,body:body===undefined?undefined:raw?body:JSON.stringify(body),signal,redirect:'manual',...(options.stream?{duplex:'half'}:{})});
    }catch(cause){
      throw failedTransport(cause,signal,options);
    }
    if(response.status>=300&&response.status<400)throw new CrewRequestError('Crew server redirected the request; check the configured URL',{code:'REDIRECT_REFUSED',status:response.status});
    const cookie=response.headers.get('set-cookie');
    if(cookie)this.cookie=cookie.split(';')[0];
    if(options.response&&response.ok)return response;
    let data;
    try{data=options.binary&&response.ok?Buffer.from(await response.arrayBuffer()):await responseData(response);}
    catch(cause){throw failedTransport(cause,signal,options,true);}
    if(!response.ok){
      const error=data&&typeof data==='object'?data.error:null;
      throw new CrewRequestError(error?.message??'Crew request failed ('+response.status+')',{code:error?.code??'HTTP_ERROR',status:response.status,details:error?.details});
    }
    return data;
  }
  get(route,options){return this.request('GET',route,undefined,options);}
  post(route,body,options){return this.request('POST',route,body,options);}
  patch(route,body,options){return this.request('PATCH',route,body,options);}
  delete(route,body,options){return this.request('DELETE',route,body,options);}
}
export function query(values={}) {const search=new URLSearchParams(Object.entries(values).filter(([,v])=>v!==undefined&&v!==true));return search.size?'?'+search:'';}

import {saveConfig} from '../client.js';
export const commands={
  async login(ctx) {
    if(ctx.options.token){ctx.client.token=ctx.options.token;await ctx.client.get('/me');await saveConfig({url:ctx.client.url,token:ctx.options.token},ctx.configFile);ctx.print({ok:true});return;}
    const email=ctx.options.email??ctx.args[0];
    const password=ctx.options.password??process.env.CREW_PASSWORD;
    if(!email||!password)throw new Error('Usage: crew login --email EMAIL --password PASSWORD, or --token TOKEN');
    const result=await ctx.client.post('/auth/login',{email,password});
    await saveConfig({url:ctx.client.url,cookie:ctx.client.cookie},ctx.configFile);
    ctx.print(result);
  },
  async whoami(ctx){ctx.print(await ctx.client.get('/me'));},
  async logout(ctx){
    const revokeSession=Boolean(ctx.client.cookie&&!ctx.client.token&&!ctx.options.local);
    if(revokeSession)await ctx.client.post('/auth/logout',{});
    await saveConfig({url:ctx.client.url},ctx.configFile);
    ctx.print({ok:true,localCredentialsRemoved:true,sessionRevoked:revokeSession});
  }
};
