import {spawn} from 'node:child_process';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {once} from 'node:events';
import path from 'node:path';
export const dataDir=path.resolve(process.env.CREW_DATA_DIR??'./data');
export async function persist(name,value){await mkdir(dataDir,{recursive:true,mode:0o700});await writeFile(path.join(dataDir,name),JSON.stringify(value,null,2)+'\n',{mode:0o600});}
export async function load(name,fallback={}){try{return JSON.parse(await readFile(path.join(dataDir,name),'utf8'));}catch(error){if(error.code==='ENOENT')return fallback;throw error;}}
export async function child(command,args,options={}) {
  const processChild=spawn(command,args,{...options,stdio:['ignore','pipe','pipe']});
  let stdout='',stderr='';
  processChild.stdout.on('data',chunk=>{stdout+=chunk;});
  processChild.stderr.on('data',chunk=>{stderr+=chunk;});
  const timer=setTimeout(()=>processChild.kill('SIGKILL'),options.deadline??20000);
  try{const [code,signal]=await once(processChild,'exit');if(code!==0)throw new Error(`${command} exited ${code??signal}: ${stderr}`);return{stdout,stderr,code};}
  finally{clearTimeout(timer);if(processChild.exitCode===null&&processChild.signalCode===null)processChild.kill('SIGKILL');}
}
export async function startServer() {
  await mkdir(dataDir,{recursive:true,mode:0o700});
  const server=spawn(process.execPath,['packages/server/src/index.js'],{env:{...process.env,PORT:'0',CREW_DATA_DIR:dataDir,CREW_SECRET:'crew-acceptance-fixed-secret'},stdio:['ignore','pipe','pipe']});
  let stdout='',stderr='';let readyResolve,readyReject;
  const ready=new Promise((resolve,reject)=>{readyResolve=resolve;readyReject=reject;});
  const timer=setTimeout(()=>readyReject(new Error('Server readiness deadline exceeded: '+stderr)),8000);
  server.stdout.on('data',chunk=>{stdout+=chunk;for(const line of stdout.split('\n')){try{const record=JSON.parse(line);if(record.ready)readyResolve(record);}catch{}}});
  server.stderr.on('data',chunk=>{stderr+=chunk;});
  server.on('error',readyReject);
  server.on('exit',(code,signal)=>readyReject(new Error(`Server exited before readiness: ${code??signal} ${stderr}`)));
